def calculate_average_scores(players):
    male_scores = []
    female_scores = []

    for player in players:
        if player['gender'] == 'male':
            male_scores.extend(player['scores'])
        else:
            female_scores.extend(player['scores'])

    male_average = sum(male_scores) / len(male_scores) if male_scores else 0
    female_average = sum(female_scores) / len(female_scores) if female_scores else 0

    return {'male': male_average, 'female': female_average}

def find_earliest_date(documents):
    import re
    from datetime import datetime

    earliest_date = None

    for document in documents:
        date_matches = re.findall(r'\d{4}-\d{2}-\d{2}', document)
        for date_str in date_matches:
            try:
                date = datetime.strptime(date_str, '%Y-%m-%d')
                if earliest_date is None or date < earliest_date:
                    earliest_date = date
            except ValueError:
                pass

    if earliest_date is None:
        return 'No date found'
    else:
        return earliest_date.strftime('%Y-%m-%d')

def calculate_batting_average(hits, at_bats):
