def mahalanobis_distance(data_point, dataset, is_cov_inv=False):
    mean_vector = np.mean(dataset, axis=0)
    if is_cov_inv:
        cov_inv = dataset
    else:
        cov_matrix = np.cov(dataset, rowvar=False)
        cov_inv = np.linalg.inv(cov_matrix)
    centered_data_point = data_point - mean_vector
    distance = np.sqrt(np.dot(np.dot(centered_data_point, cov_inv), centered_data_point))
    return distance

