def process_traffic_data(data, start_time, end_time):
    vehicle_speeds = {}

    for vehicle_id, timestamp, speed in data:
        if start_time <= timestamp <= end_time:
            if vehicle_id in vehicle_speeds:
                vehicle_speeds[vehicle_id].append(speed)
            else:
                vehicle_speeds[vehicle_id] = [speed]

    average_speeds = {}
    for vehicle_id, speeds in vehicle_speeds.items():
        average_speed = sum(speeds) / len(speeds)
        average_speeds[vehicle_id] = average_speed

    return average_speeds

def analyze_texts(texts, terms):
