def count_battles_per_general(battles):
    battle_counts = {}
    for battle in battles:
        generals = battle["generals"]
        for general in generals:
            if general in battle_counts:
                battle_counts[general] += 1
            else:
                battle_counts[general] = 1
    return battle_counts
```

