        else:
            # Handle lines without a dialogue or missing character names
            pass

    return character_lines

def calculate_average_unemployment_duration(job_loss_events, current_date):
    from datetime import datetime

    total_duration = 0
    event_count = 0

    for event in job_loss_events:
        start_date = datetime.strptime(event["start_date"], "%Y-%m-%d").date()
        end_date = datetime.strptime(event["end_date"], "%Y-%m-%d").date() if event["end_date"] else current_date

        duration = (end_date - start_date).days
        total_duration += duration
        event_count += 1

    if event_count == 0:
        return 0
    else:
        average_duration = total_duration / event_count
        return round(average_duration)

