def can_partition(nums):
    total_sum = sum(nums)
    if total_sum % 2 != 0:
        return False

    target_sum = total_sum // 2
    dp = set()
    dp.add(0)

    for num in nums:
        temp = set()
        for val in dp:
            if val + num <= target_sum:
                temp.add(val + num)
        dp |= temp

    return target_sum in dp

