def calculate_avg_goals_per_game(players):
    avg_goals = {}
    for player in players:
        name = player['name']
        goals = player['goals']
        total_goals = sum(goals)
        num_games = len(goals)
        if num_games > 0:
            avg_goals[name] = round(total_goals / num_games, 2)
        else:
            avg_goals[name] = 0.0
    return avg_goals
