def count_unique_songs(fragments):
    def permute(fragments, current_song, songs):
        if not fragments:
            songs.add(''.join(current_song))
            return

        for i, fragment in enumerate(fragments):
            remaining_fragments = fragments[:i] + fragments[i+1:]
            current_song.append(fragment)
            permute(remaining_fragments, current_song, songs)
            current_song.pop()

    songs = set()
    permute(fragments, [], songs)
    return len(songs)

