def process_student_scores(students):
    total_students = len(students)
    total_score = sum(student["score"] for student in students)
    average_score = total_score / total_students

    grade_breakdown = {}
    for student in students:
        grade = student["grade"]
        grade_breakdown[grade] = grade_breakdown.get(grade, 0) + 1

    highest_score = max(students, key=lambda x: x["score"])
    lowest_score = min(students, key=lambda x: x["score"])

    result = {
        "total_students": total_students,
        "average_score": average_score,
        "grade_breakdown": grade_breakdown,
        "highest_score": {"name": highest_score["name"], "score": highest_score["score"]},
        "lowest_score": {"name": lowest_score["name"], "score": lowest_score["score"]}
    }

    return result

