def analyze_emotional_text(text, emotionally_charged_words):
    sentences = text.split('. ') + text.split('? ') + text.split('! ')
    sentence_scores = []

    for sentence in sentences:
        if sentence:
            words = sentence.split()
            emotional_word_count = sum(word.lower() in emotionally_charged_words for word in words)
            sentence_scores.append((emotional_word_count, sentence))

    max_score = max(sentence_scores, key=lambda x: x[0])

    if max_score[0] > 0:
        return max_score[1] + '.'
    else:
        return "No emotionally charged sentence found."

