def analyze_athlete_data(athlete_data, analysis_type):
    import statistics
    import math

    if analysis_type == "average_duration":
        infection_durations = [athlete['infection_duration'] for athlete in athlete_data]
        average_duration = statistics.mean(infection_durations)
        return average_duration

    elif analysis_type == "correlation":
        infection_durations = [athlete['infection_duration'] for athlete in athlete_data]
        performance_metrics = [athlete['performance_metric'] for athlete in athlete_data]

        covariance = sum((x - statistics.mean(infection_durations)) * (y - statistics.mean(performance_metrics)) for x, y in zip(infection_durations, performance_metrics))
        covariance /= len(infection_durations)

        std_dev_infections = statistics.stdev(infection_durations)
        std_dev_performance = statistics.stdev(performance_metrics)

        if std_dev_infections == 0 or std_dev_performance == 0:
            correlation_coefficient = 0
        else:
            correlation_coefficient = covariance / (std_dev_infections * std_dev_performance)

        if correlation_coefficient > 0:
            correlation_type = "positive"
        else:
            correlation_type = "negative"

        return (correlation_coefficient, correlation_type)

