def hauntingly_reversed_string(input_string):
    # Remove spaces from the input string
    stripped_string = input_string.replace(" ", "")

    # Reverse the string
    reversed_string = stripped_string[::-1]

    # Initialize an empty string to store the output
    output_string = ""

    # Iterate over the reversed string and alternate cases
    for i, char in enumerate(reversed_string):
        if i % 2 == 0:
            output_string += char.lower()
        else:
            output_string += char.upper()

    # Reinsert spaces at their original positions
    output_string = list(output_string)
    for i, char in enumerate(input_string):
        if char == " ":
            output_string.insert(i, " ")
    output_string = "".join(output_string)

    return output_string

